insert into criteria (id, domain_id, title, requirement, indicators, evidence_expected, safeguard) values
  ('C001', 'D01', 'Plan national de développement', 'Présenter un plan clair, cohérent, chiffré et réalisable.', 'Diagnostic ; priorités ; coûts ; sources de financement ; responsables ; calendrier.', 'Programme officiel, études de faisabilité, cadre budgétaire.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C002', 'D01', 'Stratégie de développement accéléré', 'Définir des objectifs de développement à court, moyen et long terme.', 'Cibles mesurables ; échéances ; indicateurs ; mécanisme de suivi.', 'Plan pluriannuel et tableau d’indicateurs.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C003', 'D01', 'Réduction de la dépendance aux importations', 'Expliquer comment renforcer la production nationale et la substitution compétitive aux importations.', 'Filières ciblées ; productivité ; qualité ; coûts ; exportations.', 'Études sectorielles et plan industriel/agricole.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C004', 'D02', 'Économie sociale et solidaire', 'Soutenir les coopératives, entreprises sociales et initiatives économiques inclusives.', 'Cadre légal ; accès au financement ; formation ; marchés ; gouvernance.', 'Programme ESS et mesures budgétaires.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C005', 'D02', 'Économie circulaire et recyclage', 'Développer la réduction, la réutilisation, le recyclage et la valorisation des déchets.', 'Collecte ; tri ; transformation ; débouchés ; emplois ; gestion environnementale.', 'Plan de gestion des déchets et projets pilotes.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C006', 'D02', 'Inclusion économique', 'Favoriser l’accès des petites entreprises et populations vulnérables aux opportunités économiques.', 'KPI d’emploi ; accès aux marchés ; accompagnement ; couverture territoriale.', 'Programmes et critères d’éligibilité publics.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C007', 'D03', 'Absence d’appui aux groupes armés', 'Prévenir toute participation directe ou indirecte au financement, à l’armement, à la protection ou à l’organisation de groupes armés.', 'Déclarations d’intérêts ; vérifications légales ; mécanismes de signalement ; transparence.', 'Déclarations officielles et vérifications indépendantes.', 'Établir les faits par des éléments fiables et des procédures régulières.'),
  ('C008', 'D03', 'Plan de démantèlement des groupes armés', 'Présenter un plan légal, coordonné et vérifiable de démantèlement des groupes armés.', 'Désarmement ; enquêtes ; contrôle des armes ; protection des civils ; justice ; réinsertion adaptée.', 'Plan opérationnel, budget, calendrier, indicateurs.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C009', 'D03', 'Contrôle des armes et des flux financiers', 'Lutter contre le trafic d’armes, les réseaux de financement et les chaînes logistiques criminelles.', 'Contrôle frontalier ; enquêtes financières ; coopération judiciaire ; traçabilité.', 'Plan de lutte contre les trafics et rapports de résultats.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C010', 'D03', 'Protection des civils', 'Mettre la protection de la population au centre des opérations de sécurité.', 'Prévention des abus ; protection des déplacés ; accès humanitaire ; mécanismes de plainte.', 'Protocoles opérationnels et rapports de contrôle.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C011', 'D04', 'Réévaluation des partenariats existants', 'Évaluer les relations et accords actuels à l’aune des intérêts nationaux.', 'Audit des accords ; coûts ; bénéfices ; obligations ; résultats.', 'Inventaire des accords et évaluations publiées.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C012', 'D04', 'Renégociation et diversification', 'Identifier les accords à réviser et les nouveaux partenariats à explorer.', 'Analyse juridique ; objectifs ; transfert de compétences ; risques ; alternatives.', 'Stratégie diplomatique et économique.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C013', 'D04', 'Souveraineté dans les accords', 'Préserver la capacité de décision nationale et éviter les dépendances excessives.', 'Clauses de souveraineté ; transparence ; arbitrage ; dette soutenable.', 'Textes d’accords et analyses d’impact.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C014', 'D05', 'Absence d’implication dans la corruption', 'Le candidat doit pouvoir rendre compte de son intégrité et de toute implication établie dans des faits de corruption, directe ou indirecte.', 'Vérification des fonctions antérieures ; intérêts ; patrimoine ; décisions judiciaires ; conflits d’intérêts.', 'Déclarations patrimoniales, décisions définitives, rapports d’audit.', 'Ne pas assimiler une accusation ou une rumeur à une culpabilité.'),
  ('C015', 'D05', 'Réputation et intégrité irréprochables', 'Évaluer les faits documentés susceptibles d’affecter la confiance publique.', 'Sources corroborées ; réponse du candidat ; statut des procédures ; décisions judiciaires.', 'Dossiers publics fiables et contradictoires.', 'La simple mention d’un nom dans un scandale ne suffit pas à établir une faute.'),
  ('C016', 'D05', 'Transparence patrimoniale', 'Publier les déclarations de patrimoine et d’intérêts prévues par la loi.', 'Déclarations ; vérification ; évolution patrimoniale ; conflits d’intérêts.', 'Déclarations officielles et contrôles compétents.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C017', 'D05', 'Marchés publics transparents', 'Garantir la transparence des contrats, appels d’offres et dépenses publiques.', 'Publication des appels d’offres ; bénéficiaires effectifs ; audits ; sanctions.', 'Portail de marchés publics et rapports d’audit.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C018', 'D05', 'Indépendance des organes de contrôle', 'Renforcer les institutions d’audit, de contrôle et de lutte contre la corruption.', 'Autonomie ; ressources ; nominations transparentes ; suivi des recommandations.', 'Propositions législatives et budgétaires.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C019', 'D06', 'Scolarité gratuite et obligatoire', 'Garantir une scolarité universelle, gratuite et obligatoire de la maternelle à la fin du secondaire.', 'Couverture ; frais supprimés ; écoles ; enseignants ; transport ; repas si prévu ; taux de fréquentation.', 'Plan éducatif chiffré, budget et statistiques.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C020', 'D06', 'Refondation du système éducatif', 'Réformer les programmes et les méthodes d’apprentissage.', 'Programme national ; langues d’enseignement ; sciences ; numérique ; histoire ; formation des enseignants.', 'Curriculum proposé et calendrier de réforme.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C021', 'D06', 'Formation de citoyens responsables', 'Former une nouvelle génération consciente de son identité nationale, de ses droits et de ses responsabilités civiques.', 'Éducation civique ; pensée critique ; participation ; respect des biens publics ; inclusion.', 'Programmes scolaires et outils d’évaluation.', 'Éviter l’endoctrinement : pluralisme, liberté de conscience et esprit critique.'),
  ('C022', 'D06', 'Formation technique et professionnelle', 'Adapter la formation aux besoins économiques du pays.', 'Centres ; apprentissage ; partenariats ; insertion professionnelle.', 'Plan de formation et données d’insertion.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C023', 'D07', 'Accès aux soins', 'Améliorer l’accès territorial et financier aux soins de santé.', 'Centres ; personnel ; médicaments ; coûts ; couverture.', 'Plan sanitaire et budget.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C024', 'D07', 'Renforcement des hôpitaux publics', 'Moderniser les infrastructures et la gestion hospitalière.', 'Équipements ; maintenance ; ressources humaines ; qualité ; disponibilité.', 'Inventaire et plan d’investissement.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C025', 'D07', 'Protection sociale', 'Développer des mécanismes accessibles de protection sociale.', 'Couverture ; ciblage ; financement ; transparence ; évaluation.', 'Cadre de protection sociale.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C026', 'D08', 'Relance agricole', 'Augmenter la production agricole et la résilience des exploitations.', 'Irrigation ; semences ; stockage ; routes agricoles ; crédit ; rendement.', 'Plan agricole et indicateurs de production.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C027', 'D08', 'Industrialisation et transformation locale', 'Développer la transformation des matières premières et produits locaux.', 'Zones industrielles ; énergie ; formation ; accès aux marchés ; valeur ajoutée.', 'Plan industriel et études de faisabilité.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C028', 'D08', 'Énergie et infrastructures productives', 'Améliorer la disponibilité et la fiabilité de l’énergie et des infrastructures économiques.', 'Capacité ; coût ; continuité ; entretien ; couverture territoriale.', 'Plan énergétique et projets chiffrés.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C029', 'D08', 'PME et entrepreneuriat', 'Améliorer l’environnement des petites et moyennes entreprises.', 'Formalisation ; financement ; fiscalité ; accompagnement ; marchés publics.', 'Réformes et programmes.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C030', 'D09', 'Décentralisation territoriale', 'Renforcer les capacités et responsabilités des collectivités territoriales.', 'Compétences ; ressources ; transferts ; contrôle ; participation locale.', 'Plan de décentralisation et cadre budgétaire.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C031', 'D09', 'Déconcentration administrative', 'Rapprocher les services de l’État des citoyens dans les départements et communes.', 'Services disponibles ; délais ; effectifs ; budgets ; guichets locaux.', 'Carte des services et plan de déploiement.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C032', 'D09', 'Investissements équilibrés', 'Répartir les investissements publics sur l’ensemble du territoire.', 'Dépenses par département ; critères d’allocation ; suivi des projets.', 'Budget territorialisé.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C033', 'D10', 'Protection des ressources naturelles', 'Protéger les sols, forêts, bassins versants et ressources en eau.', 'Surveillance ; restauration ; gestion locale ; application des lois.', 'Plan environnemental et indicateurs.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C034', 'D10', 'Gestion des déchets', 'Mettre en place une politique de collecte, traitement et valorisation des déchets.', 'Couverture ; sites ; recyclage ; santé publique ; coûts.', 'Plan national de gestion des déchets.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C035', 'D10', 'Prévention des catastrophes', 'Renforcer la prévention, l’alerte et la résilience.', 'Cartographie des risques ; plans locaux ; abris ; exercices ; systèmes d’alerte.', 'Plan de réduction des risques.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C036', 'D11', 'Compétences et expérience', 'Présenter un parcours vérifiable et les compétences nécessaires à la fonction.', 'Expérience de gestion ; réalisations ; connaissance institutionnelle ; équipe.', 'CV vérifié, bilan public et références.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C037', 'D11', 'Composition de l’équipe gouvernementale', 'S’engager à sélectionner les responsables selon la compétence et l’intégrité.', 'Critères de nomination ; transparence ; déclaration d’intérêts ; évaluation.', 'Politique de nomination.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C038', 'D11', 'Respect de l’ordre constitutionnel', 'S’engager à respecter la séparation des pouvoirs et les limites du mandat présidentiel.', 'Engagement public ; pratiques institutionnelles ; respect des contre-pouvoirs.', 'Programme et bilan institutionnel.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C039', 'D12', 'Rapports publics périodiques', 'Rendre compte régulièrement de l’exécution du programme.', 'Rapports trimestriels/annuels ; indicateurs ; dépenses ; écarts.', 'Engagement de publication.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C040', 'D12', 'Évaluation indépendante', 'Accepter des évaluations indépendantes des politiques publiques.', 'Audits ; accès aux données ; réponse aux recommandations.', 'Protocole d’évaluation.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C041', 'D12', 'Consultation citoyenne', 'Organiser la consultation sur les grandes orientations nationales.', 'Mécanismes ; représentation territoriale ; retours publics.', 'Plan de participation.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C042', 'D13', 'Cadre légal neutre pour les lieux de culte', 'Encadrer l’enregistrement et le fonctionnement des organisations et lieux de culte selon des règles générales.', 'Sécurité des bâtiments ; urbanisme ; protection des mineurs ; obligations légales ; transparence financière applicable.', 'Projet de cadre réglementaire.', 'Neutralité religieuse et égalité de traitement ; aucune restriction fondée sur la croyance.'),
  ('C043', 'D13', 'Prévention des abus et activités illégales', 'Prévenir l’exploitation, les violences, la fraude et les abus commis sous couvert d’une organisation.', 'Signalement ; enquêtes ; protection des victimes ; sanctions judiciaires.', 'Protocoles et statistiques d’application.', 'Les sanctions portent sur des actes prouvés, non sur une doctrine ou une religion.'),
  ('C044', 'D14', 'Histoire et patrimoine national', 'Renforcer l’enseignement de l’histoire et du patrimoine d’Haïti.', 'Contenus ; ressources ; formation ; accès régional.', 'Programme éducatif et culturel.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C045', 'D14', 'Cohésion et participation citoyenne', 'Promouvoir la participation, le respect mutuel et la responsabilité collective.', 'Initiatives locales ; inclusion ; participation ; prévention des discriminations.', 'Plan de cohésion sociale.', 'Respect du pluralisme et des libertés individuelles.'),
  ('C046', 'D15', 'Position sur le dossier PetroCaribe', 'Prendre une position publique claire sur la transparence, les enquêtes et les suites du dossier.', 'Engagement de coopération ; état des procédures ; publication d’informations légalement accessibles.', 'Déclarations publiques et documents officiels.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C047', 'D15', 'Responsabilités et poursuites', 'Soutenir des procédures indépendantes concernant les responsabilités légalement établies.', 'Indépendance judiciaire ; preuves ; procédures régulières ; égalité devant la loi.', 'Décisions judiciaires et rapports officiels.', 'Ne pas présumer la culpabilité ; respecter la présomption d’innocence.'),
  ('C048', 'D15', 'Récupération des avoirs', 'Soutenir, lorsque les faits sont établis, la récupération des fonds et avoirs publics détournés.', 'Entraide judiciaire ; traçabilité ; recouvrement ; publication des résultats.', 'Rapports de recouvrement et décisions.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C049', 'D16', 'Renforcement des représentations civiles de l’État', 'Renforcer les délégations, directions départementales et services civils de l’État dans les dix départements.', 'Personnel ; budget ; équipements ; services accessibles ; objectifs départementaux.', 'Plan de déploiement territorial.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C050', 'D16', 'Capacité opérationnelle locale', 'Donner aux services déconcentrés les moyens de remplir leurs missions.', 'Effectifs ; formation ; locaux ; numérique ; délais de service.', 'Inventaire et plan d’investissement.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C051', 'D16', 'Coordination territoriale', 'Clarifier les responsabilités entre administration centrale, délégations et collectivités.', 'Attributions ; protocoles ; coordination ; reddition de comptes.', 'Textes et organigrammes proposés.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C052', 'D17', 'Priorité diplomatique de développement : Chine', 'Inscrire la République populaire de Chine comme partenaire prioritaire à explorer pour les partenariats de développement.', 'Dialogue diplomatique ; faisabilité ; secteurs ; conditions ; analyse des risques.', 'Stratégie diplomatique et études de projets.', 'La priorité proposée ne dispense pas d’évaluer les accords ni de respecter le cadre diplomatique et juridique applicable.'),
  ('C053', 'D17', 'Partenariats diversifiés', 'Étudier d’autres partenaires potentiels sans dépendance exclusive.', 'Comparaison des offres ; risques ; coûts ; transferts de compétences.', 'Études comparatives et stratégie de diversification.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C054', 'D17', 'Secteurs de coopération', 'Identifier les domaines de coopération prioritaires.', 'Infrastructures ; agriculture ; énergie ; industrie ; santé ; numérique ; formation ; environnement.', 'Portefeuille de projets préparé.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C055', 'D17', 'Évaluation des accords', 'Évaluer les accords existants et futurs selon l’intérêt national.', 'Dette ; coûts complets ; retombées ; clauses ; transparence ; maintenance.', 'Analyses d’impact publiées.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C056', 'D18', 'Modernisation des FAd’H', 'Inscrire la modernisation des Forces armées d’Haïti dans le programme présidentiel.', 'Doctrine ; formation ; équipements adaptés ; logistique ; budget ; maintenance.', 'Plan de modernisation et budget.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C057', 'D18', 'Défense du territoire', 'Développer les capacités légales de surveillance et de protection du territoire.', 'Frontières ; domaine maritime ; espace aérien ; coordination ; secours.', 'Plan de défense et indicateurs.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C058', 'D18', 'Génie militaire et secours', 'Renforcer les capacités d’appui aux catastrophes et aux infrastructures d’intérêt public.', 'Formation ; équipements de secours ; coordination civile.', 'Plan de préparation et d’intervention.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C059', 'D18', 'Partenariats militaires diversifiés', 'Explorer des partenaires autres que les États-Unis pour la formation et la modernisation, selon les besoins nationaux.', 'Études comparatives ; conformité ; coût ; maintenance ; formation ; garanties.', 'Évaluations des offres et accords publiables.', 'Aucune acquisition ou coopération ne doit contourner les obligations légales ou les contrôles démocratiques.'),
  ('C060', 'D19', 'Nouvelle doctrine de la PNH', 'Proposer un changement de paradigme et une nouvelle orientation de la Police nationale.', 'Prévention ; renseignement criminel légal ; enquête ; police de proximité ; protection des citoyens.', 'Nouvelle doctrine et plan de réforme.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C061', 'D19', 'Professionnalisation et formation', 'Réformer la formation initiale et continue des policiers.', 'Curriculum ; droits fondamentaux ; enquêtes ; gestion des foules ; discipline.', 'Programmes de formation et évaluations.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C062', 'D19', 'Police scientifique et investigation', 'Renforcer les capacités d’enquête et de traitement des preuves.', 'Laboratoires ; chaîne de conservation ; personnel ; procédures.', 'Plan technique et budget.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C063', 'D19', 'Intégrité et contrôle interne', 'Renforcer l’inspection générale et les mécanismes de plainte.', 'Indépendance ; enquêtes ; statistiques ; protection des plaignants.', 'Rapports d’inspection et protocoles.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C064', 'D19', 'Police de proximité', 'Restaurer la confiance entre la population et la police.', 'Consultations locales ; présence ; résolution de problèmes ; plaintes.', 'Plan territorial et enquêtes de confiance.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C065', 'D20', 'Coordination PNH–FAd’H–justice', 'Définir les responsabilités et mécanismes de coordination des institutions de sécurité.', 'Mandats ; protocoles ; partage légal d’information ; chaîne de commandement.', 'Cadre légal et opérationnel.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C066', 'D20', 'Contrôle civil et démocratique', 'Garantir le contrôle institutionnel des forces de sécurité.', 'Contrôle budgétaire ; contrôle parlementaire compétent ; justice ; mécanismes de plainte.', 'Textes, budgets et rapports.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C067', 'D21', 'Financement direct par les partenaires', 'Privilégier les projets financés directement par les partenaires, sans transfert des fonds du projet à l’État haïtien pour administration.', 'Modalités de paiement direct ; audit ; traçabilité ; prévention des conflits d’intérêts.', 'Convention de financement et mécanismes d’audit.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C068', 'D21', 'Exécution directe par les partenaires', 'Prévoir, lorsque cela est faisable et avantageux, l’exécution par les partenaires ou leurs opérateurs contractuels.', 'Responsabilités ; sélection ; sous-traitance ; délais ; garanties.', 'Contrats et cahiers des charges.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C069', 'D21', 'Contribution haïtienne en nature et expertise', 'L’État contribue par la mobilisation de main-d’œuvre, d’expertise locale et de facilités institutionnelles, selon les conventions.', 'Profils ; volumes de travail ; valorisation des apports ; formation ; sécurité au travail.', 'Plan de contribution nationale.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C070', 'D21', 'Contrôle indépendant de qualité', 'Mettre en place un contrôle technique indépendant des coûts, matériaux, normes et résultats.', 'Inspections ; essais ; certifications ; réception provisoire et définitive.', 'Rapports de contrôle et certificats.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C071', 'D21', 'Propriété, maintenance et transfert de compétences', 'Prévoir la propriété des ouvrages, leur entretien et la formation des équipes haïtiennes.', 'Clauses de propriété ; garanties ; budget de maintenance ; transfert de compétences.', 'Convention et plan de maintenance.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C072', 'D21', 'Transparence et risques', 'Publier les conventions et évaluer les engagements indirects ou coûts supportés par Haïti.', 'Exemptions ; terrains ; coûts d’opportunité ; passifs éventuels ; audits.', 'Analyse d’impact et registre des engagements.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
  ('C073', 'D22', 'Rétablissement de l’autorité de l’État', 'Présenter un plan de restauration de l’autorité publique sur tout le territoire.', 'Présence des services ; exécution des décisions ; accès aux services ; contrôle légal du territoire.', 'Plan national, calendrier et indicateurs.', 'Application conforme à la Constitution, aux lois et aux droits fondamentaux.'),
